import { createWriteStream } from 'node:fs';
import { mkdtemp, readFile, rm, stat } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path, { basename, dirname, join } from 'node:path';
import { pipeline } from 'node:stream/promises';
import { createGzip } from 'node:zlib';
import { buildApp, buildStudio, compareDependencyVersions, } from '@sanity/cli-build/_internal/build';
import { getLocalPackageVersion } from '@sanity/cli-core';
import { pack } from 'tar-fs';
export const BUNDLE_SPECS = {
    'sanity.studio': { requiresAppId: true, build: buildStudioBundle },
    'sanity.application': { requiresAppId: true, build: buildApplicationBundle },
    'sanity.installation.config': { requiresAppId: false, build: buildInstallationConfigBundle },
};
export async function prepareBundleAsset({ blueprintFileDir, resource, }) {
    // The lookup can't prove it yields the spec matching this R, so it's asserted once here.
    const spec = BUNDLE_SPECS[resource.type];
    const appId = getAppId(resource);
    if (spec.requiresAppId && !appId) {
        return {
            success: false,
            async cleanup() { },
            error: `Unable to determine appId for ${resource.type} resource '${resource.name}'`,
        };
    }
    let cleanup = async () => { };
    const assetPath = String(resource.root);
    const workDir = path.resolve(blueprintFileDir, assetPath);
    // Defence in depth alongside blueprints-node's own check: an absolute path or one
    // that climbs above the blueprint dir would bundle files outside the project.
    if (path.isAbsolute(assetPath) || path.relative(blueprintFileDir, workDir).startsWith('..')) {
        return {
            success: false,
            cleanup,
            error: `Property 'root' on resource with type '${resource.type}' must be under the blueprint directory`,
        };
    }
    try {
        const workDirStat = await stat(workDir);
        if (!workDirStat.isDirectory()) {
            return {
                success: false,
                cleanup,
                error: `Property 'root' on resource with type '${resource.type}' must be a directory`,
            };
        }
    }
    catch (error) {
        const msg = error instanceof Error ? error.message : String(error);
        return {
            success: false,
            cleanup,
            error: `Unable to read given 'root' on resource with type '${resource.type}': ${msg}`,
        };
    }
    try {
        const outDir = await mkdtemp(join(tmpdir(), `bundle-`));
        const outFile = `${outDir}.tar.gz`;
        cleanup = async () => {
            await rm(outDir, { force: true, recursive: true });
            await rm(outFile, { force: true });
        };
        let mismatchedPackages;
        try {
            ;
            ({ mismatchedPackages } = await spec.build({
                resource,
                appId,
                workDir,
                outDir,
                output: createSilentOutput(),
                eventListener,
            }));
        }
        catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            return {
                success: false,
                cleanup,
                error: message,
            };
        }
        await pipeline(pack(dirname(outDir), { entries: [basename(outDir)] }), createGzip(), createWriteStream(outFile));
        const buffer = await readFile(outFile);
        return {
            success: true,
            cleanup,
            outputBuffer: buffer,
            fileExtension: 'tar.gz',
            assetParameter: 'root',
            metadata: {
                sanityVersion: await getInstalledSanityVersion(workDir),
                mismatchedPackages,
                assetBytes: buffer.length,
            },
        };
    }
    catch (error) {
        return {
            success: false,
            cleanup,
            error: error instanceof Error ? error.message : String(error),
        };
    }
}
async function buildStudioBundle({ resource, appId, workDir, outDir, output, eventListener, }) {
    let mismatchedPackages;
    await buildStudio({
        appId,
        autoUpdatesEnabled: resource.autoUpdates.enabled,
        checkAppId() { },
        async compareDependencyVersions(packages) {
            const result = await compareDependencyVersions(packages, workDir, { appId });
            mismatchedPackages = result.mismatched.map((m) => m.pkg);
            return result;
        },
        determineBasePath() {
            return resource.basePath ?? '/';
        },
        // a studio is a standalone app, not a workbench module-federation app
        isApp: false,
        isBlueprints: true,
        isWorkbenchApp: false,
        minify: resource.minify ?? true,
        outDir,
        output,
        reactCompiler: resource.reactCompiler || false,
        schemaExtraction: undefined,
        sourceMap: resource.sourceMap ?? false,
        stats: false,
        unattendedMode: true,
        // TODO pass in vite config from the studio resource
        vite: undefined,
        workDir,
        eventListener,
    });
    return { mismatchedPackages };
}
async function buildApplicationBundle({ resource, appId, workDir, outDir, output, eventListener, }) {
    const views = resource.views ?? [];
    const [window, extraWindow] = views.filter((v) => v.type === 'app');
    if (extraWindow) {
        throw new Error(`Application resource '${resource.name}' declares more than one window view; at most one is allowed`);
    }
    await buildApp({
        ...sharedBuildAppOptions({ appId, workDir, outDir, output, eventListener }),
        appId,
        appTitle: resource.title,
        entry: window?.src,
        workbenchAppId: appId,
        exposes: {
            views: views.map(toWorkbenchView),
            webWorkers: resource.webWorkers,
        },
    });
    // a workbench app never auto-updates, so no dependency mismatches are compared
    return {};
}
async function buildInstallationConfigBundle({ resource, workDir, outDir, output, eventListener, }) {
    await buildApp({
        ...sharedBuildAppOptions({ appId: undefined, workDir, outDir, output, eventListener }),
        appId: undefined,
        appTitle: undefined,
        entry: undefined,
        workbenchAppId: undefined,
        exposes: { config: { appType: resource.appType, fields: resource.fields } },
    });
    return {};
}
// Options a workbench build (application or installation config) always sets the
// same way; each caller adds only what differs (identity, entry, exposes).
function sharedBuildAppOptions({ appId, workDir, outDir, output, eventListener, }) {
    return {
        autoUpdatesEnabled: false,
        checkAppId() { },
        async compareDependencyVersions(packages) {
            return compareDependencyVersions(packages, workDir, { appId });
        },
        determineBasePath() {
            return '/';
        },
        isWorkbenchApp: true,
        isBlueprints: true,
        minify: true,
        outDir,
        output,
        reactCompiler: false,
        schemaExtraction: undefined,
        sourceMap: false,
        stats: false,
        unattendedMode: true,
        vite: undefined,
        workDir,
        eventListener,
    };
}
// blueprints-node emits `type` (window views as `app`); workbench-cli discriminates on `surface`.
function toWorkbenchView(view) {
    switch (view.type) {
        case 'app': {
            const { type: _type, ...rest } = view;
            return { ...rest, surface: 'window' };
        }
        case 'panel': {
            const { type, ...rest } = view;
            return { ...rest, surface: type };
        }
        case 'asset_source': {
            const { type, ...rest } = view;
            return { ...rest, surface: type };
        }
        case 'tile': {
            const { type, ...rest } = view;
            return { ...rest, surface: type };
        }
    }
}
const eventListener = {
    onBuildFail({ message }) {
        throw new Error(message);
    },
    onInvalidStyledComponentsVersionRange({ message }) {
        throw new Error(message);
    },
    onNoDeclaredStyledComponentsVersion({ message }) {
        throw new Error(message);
    },
    onNoInstalledSanityVersion({ message }) {
        throw new Error(message);
    },
    onNoInstalledStyledComponentsVersion({ message }) {
        throw new Error(message);
    },
    onPreReleaseInNonInteractiveAutoUpdate({ message }) {
        throw new Error(message);
    },
};
function createSilentOutput() {
    return {
        error(input, options) {
            if (typeof options?.exit === 'number') {
                if (input instanceof Error) {
                    throw input;
                }
                throw new Error(input);
            }
            return undefined;
        },
        log() { },
        warn(input) {
            return input;
        },
    };
}
async function getInstalledSanityVersion(workDir) {
    try {
        return (await getLocalPackageVersion('sanity', workDir)) ?? undefined;
    }
    catch {
        return undefined;
    }
}
function getAppId(resource) {
    if ('externalId' in resource && typeof resource.externalId === 'string' && resource.externalId) {
        return resource.externalId;
    }
    else if (resource.lifecycle?.ownershipAction?.type === 'attach') {
        return resource.lifecycle.ownershipAction.id;
    }
    return undefined;
}
